import * as THREE from 'three';
import { Hypercube } from '..';

export class DoorOuter {
	public hypercube: Hypercube;
	public meshGroup: THREE.Group;

	private open = false;

	private closedZ = 0;
	private openZ = 0;
	private targetZ = 0;
	private speed = 0.01;

	private clippingPlane = new THREE.Plane(new THREE.Vector3(0, 0, -1), 18);

	constructor(hypercube: Hypercube, meshGroup: THREE.Group) {
		this.hypercube = hypercube;
		this.meshGroup = meshGroup;

		this.closedZ = meshGroup.position.z;

		const offset = 25;
		this.openZ = this.closedZ + offset;
		this.targetZ = this.closedZ;

		this.applyClipping(this.meshGroup);

		this.hypercube.core.scene.add(this.meshGroup);
	}

	public update() {
		this.meshGroup.position.z += (this.targetZ - this.meshGroup.position.z) * this.speed;
	}

	public onClick() {
		this.open = !this.open;
		this.targetZ = this.open ? this.openZ : this.closedZ;
	}

	private applyClipping(group: THREE.Group) {
		group.traverse((child) => {
			if ((child as THREE.Mesh).isMesh) {
				const mesh = child as THREE.Mesh;
				const material = mesh.material;

				if (Array.isArray(material)) {
					material.forEach((mat) => {
						// prettier-ignore
						if ((mat as THREE.Material).clippingPlanes !== undefined) {
                            const m = mat as THREE.MeshStandardMaterial;
                            m.clippingPlanes = [this.clippingPlane];
                            m.clipShadows = true;
                        }
					});
				} else {
					if ((material as THREE.Material).clippingPlanes !== undefined) {
						const m = material as THREE.MeshStandardMaterial;
						m.clippingPlanes = [this.clippingPlane];
						m.clipShadows = true;
					}
				}
			}
		});
	}
}
