import * as THREE from 'three';
import { OrbitControls } from 'three-orbitcontrols-ts';
import { ThreeCore } from '..';

import { config } from '../../Utils/config';

export class CameraWrapper {
	public core: ThreeCore;
	public controls: OrbitControls;
	public camera: THREE.PerspectiveCamera;

	private cameraPositionStartVec = new THREE.Vector3(0, -2000, 0);
	private cameraPositionEndVec = new THREE.Vector3(0, -150, 0);

	private cameraTargetStartVec = new THREE.Vector3(0, 0, 0);
	private cameraTargetEndVec = new THREE.Vector3(0, 0, 0);

	private startTime = null;
	private _duration = 1000;
	private t = 0.0;

	constructor(core: ThreeCore) {
		this.core = core;
		this.camera = new THREE.PerspectiveCamera(30, this.core.host.clientWidth / this.core.host.clientHeight, 3, 3000);
		this.controls = new OrbitControls(this.camera, this.core.renderer.domElement as unknown as HTMLElement);

		this.camera.position.set(this.cameraPositionStartVec.x, this.cameraPositionStartVec.y, this.cameraPositionStartVec.z);

		this.camera.up.set(0, 0, 1);
		this.controls.minPolarAngle = 0;
		this.controls.target.set(this.cameraTargetStartVec.x, this.cameraTargetStartVec.y, this.cameraTargetStartVec.z);
		this.controls.maxPolarAngle = Math.PI / 2;
		this.controls.minDistance = config.scene.cameraMinDistance;
		this.controls.maxDistance = config.scene.cameraMaxDistance;
		this.controls.update();
	}
	public onWindowResize() {
		this.camera.aspect = this.core.host.clientWidth / this.core.host.clientHeight;
		this.camera.updateProjectionMatrix();
	}
	public set duration(value: number) {
		this._duration = value;
	}
	public moveCamera(x: number, y: number, z: number) {
		this.cameraPositionStartVec.x = this.camera.position.x;
		this.cameraPositionStartVec.y = this.camera.position.y;
		this.cameraPositionStartVec.z = this.camera.position.z;
		this.cameraPositionEndVec.x = x;
		this.cameraPositionEndVec.y = y;
		this.cameraPositionEndVec.z = z;
		this.t = 0.0;
		this.startTime = undefined;
	}
	public moveTarget(x: number, y: number, z: number) {
		this.cameraTargetStartVec.x = this.controls.target.x;
		this.cameraTargetStartVec.y = this.controls.target.y;
		this.cameraTargetStartVec.z = this.controls.target.z;
		this.cameraTargetEndVec.x = x;
		this.cameraTargetEndVec.y = y;
		this.cameraTargetEndVec.z = z;
		this.t = 0.0;
		this.startTime = undefined;
	}
	public update() {
		if (this.t < 1) {
			this.cameraAniTarget();
			this.controls.update();
		}
	}
	public log() {
		console.log(`
			Camera: ${this.camera.position.x.toFixed(2)}, ${this.camera.position.y.toFixed(2)}, ${this.camera.position.z.toFixed(2)}
			Target: ${this.controls.target.x.toFixed(2)}, ${this.controls.target.y.toFixed(2)}, ${this.controls.target.z.toFixed(2)}
			`);
	}
	private cameraAniTarget() {
		const time = performance.now();

		if (!this.startTime) this.startTime = time;

		const elapsed = time - this.startTime;
		const t = Math.min(elapsed / this._duration, 1);
		this.t = t;

		if (this.t < 1) {
			const easeOut = 1 - Math.pow(1 - t, 4); // cubic easing out

			this.controls.enabled = false;

			this.controls.target.x = this.cameraTargetStartVec.x + (this.cameraTargetEndVec.x - this.cameraTargetStartVec.x) * easeOut;
			this.controls.target.y = this.cameraTargetStartVec.y + (this.cameraTargetEndVec.y - this.cameraTargetStartVec.y) * easeOut;
			this.controls.target.z = this.cameraTargetStartVec.z + (this.cameraTargetEndVec.z - this.cameraTargetStartVec.z) * easeOut;

			this.controls.enabled = true;
			this.camera.lookAt(this.controls.target);

			this.camera.position.x = this.cameraPositionStartVec.x + (this.cameraPositionEndVec.x - this.cameraPositionStartVec.x) * easeOut;
			this.camera.position.y = this.cameraPositionStartVec.y + (this.cameraPositionEndVec.y - this.cameraPositionStartVec.y) * easeOut;
			this.camera.position.z = this.cameraPositionStartVec.z + (this.cameraPositionEndVec.z - this.cameraPositionStartVec.z) * easeOut;

			this.camera.lookAt(this.controls.target);
		}
	}
}
