import * as THREE from 'three';

import { AppCore } from '../';
import { CLICK_TYPE } from '../../Utils/const';

export class ActiveCommand {
	public appCore: AppCore;

	public selectedMesh: THREE.Object3D | undefined = undefined;

	constructor(appCore: AppCore) {
		this.appCore = appCore;
	}
	public onMouseEventListener(e: MouseEvent, type: CLICK_TYPE) {
		// console.log(e, type, '!!!!');
		if (type === CLICK_TYPE.LEFT) {
			this.mouseLeftClickPre(e);
			return;
		} else if (type === CLICK_TYPE.MIDDLE) {
			this.mouseMiddleClickPre(e);
			return;
		} else if (type === CLICK_TYPE.DOWN_RIGHT) {
			this.mouseRightClickPre(e);
			return;
		} else if (type === CLICK_TYPE.DOUBLE) {
			this.mouseDoubleClickPre(e);
			return;
		} else if (type === CLICK_TYPE.MOVE) {
			this.mouseMovePre(e);
			return;
		} else if (type === CLICK_TYPE.DRAG) {
			this.mouseDragPre(e);
			return;
		} else if (type === CLICK_TYPE.DOWN) {
			this.mouseDownPre(e);
			return;
		} else if (type === CLICK_TYPE.WHEEL) {
			this.mouseWheelPre(e);
			return;
		} else if (type === CLICK_TYPE.UP) {
			this.mouseUpPre(e);
			return;
		}
	}
	public mouseDown(e: MouseEvent) {
		/* */
	}
	public mouseDownPre(e: MouseEvent) {
		this.mouseDown(e);
	}
	public mouseLeftClick(e: MouseEvent) {
		const mesh = onClick(this.appCore.threeCore.host, this.appCore.threeCore.cameraWrapper.camera, this.appCore.threeCore.scene, e);
		console.log('click', mesh.name, mesh);
		console.log(mesh.geometry, mesh.material);
		this.selectedMesh = mesh;
		// console.log(mesh.name, e, "core");

		if (mesh.name === 'mesh11848' || mesh.name === 'Object991') {
			this.appCore.hyperCube.clickDoorInner();
		}
		if (mesh.name === 'Object981') {
			this.appCore.hyperCube.clickDoorOuter();
		}
		if (mesh.name === 'Object984') {
			this.appCore.hyperCube.showCamera();
		}
		if (mesh.name === 'Object987') {
			this.appCore.hyperCube.showGraph();
		}
		if (mesh.name === 'Object996') {
			this.appCore.hyperCube.showGraphDrone();
		}
	}
	public mouseLeftClickPre(e: MouseEvent) {
		// console.log("left click");
		this.mouseLeftClick(e);
	}
	public MouseMiddleClick(e: MouseEvent) {
		/* */
	}
	public mouseMiddleClickPre(e: MouseEvent) {
		this.MouseMiddleClick(e);
	}
	public MouseRightClick(e: MouseEvent) {
		/* */
	}
	public mouseRightClickPre(e: MouseEvent) {
		this.MouseRightClick(e);
	}
	public mouseUp(e: MouseEvent) {
		/* */
	}
	public mouseUpPre(e: MouseEvent) {
		this.mouseUp(e);
	}
	public mouseDoubleClick(e: MouseEvent) {
		/* */
	}
	public mouseDoubleClickPre(e: MouseEvent) {
		// console.log("d click");
		this.mouseDoubleClick(e);
	}
	public mouseMove(e: MouseEvent) {
		/* */
	}
	public mouseMovePre(e: MouseEvent) {
		// console.log("move");

		this.mouseMove(e);
	}
	public mouseDrag(e: MouseEvent) {
		/* */
	}
	public mouseDragPre(e: MouseEvent) {
		// console.log("drag");
		this.mouseDrag(e);
	}
	public mouseWheel(e: MouseEvent) {
		/* */
	}
	public mouseWheelPre(e: MouseEvent) {
		// console.log("drag");
		this.mouseWheel(e);
	}
}

const onClick = (div: HTMLElement, camera: THREE.PerspectiveCamera, scene: THREE.Scene, event) => {
	const raycaster = new THREE.Raycaster();
	const mouse = new THREE.Vector2();

	mouse.x = (event.clientX / div.clientWidth) * 2 - 1;
	mouse.y = -(event.clientY / div.clientHeight) * 2 + 1;

	raycaster.setFromCamera(mouse, camera);

	const intersects = raycaster.intersectObjects(scene.children, true);

	const visibleIntersects = intersects.filter((i) => i.object.visible);
	console.log(visibleIntersects);
	if (visibleIntersects.length > 0) {
		const selectedObject = visibleIntersects[0].object;
		// console.log("Selected object:", selectedObject);

		// console.log('Name:', selectedObject.name);
		// console.log("position:", selectedObject.position);
		// console.log("scale:", selectedObject.scale);
		// console.log("Material:", selectedObject.material);
		// selectedObject.position.y += 100;

		if (selectedObject.name === 'ground') {
			return undefined;
		}
		return selectedObject;
	} else {
		// console.log("noting selected");
		return undefined;
	}
};
