import * as THREE from 'three';
import { AppCore } from '../';
import { loadFBX } from '../../Utils';

export class Substation {
	public appCore: AppCore;
	constructor(appCore: AppCore) {
		this.appCore = appCore;
		this.init();
	}
	async init() {
		let files = [
			'substation-01.fbx',
			// "solarPanel.fbx",
			// "door-B-1.fbx",
			// "door-B-2.fbx",
		];
		let scale = 0.005;

		console.log(files);
		await this.loadAllModels(files, scale, -15, 70, -18);

		files = [
			'substation-02.fbx',
			// "solarPanel.fbx",
			// "door-B-1.fbx",
			// "door-B-2.fbx",
		];
		scale = 0.005;
		await this.loadAllModelsDD(files, scale, 70, 0, -15);
	}
	private loadAllModels = async (files, scale, x: number, y: number, z: number) => {
		try {
			const loadPromises = files.map((file) => loadFBX(process.env.PUBLIC_URL + '/static/data/model/' + file, scale));
			const fbxModels = await Promise.all(loadPromises);
			// console.log('dd');
			fbxModels.forEach((fbx) => {
				fbx.rotation.x = Math.PI / 2;
				// fbx.position.z = -18;
				// console.log(fbx);
				fbx.position.set(x, y, z);
				this.appCore.threeCore.scene.add(fbx);
			});
		} catch (error) {
			console.error('fail to load :', error);
		}
	};

	private loadAllModelsDD = async (files: string[], scale: number, x: number, y: number, z: number) => {
		try {
			// 하나의 FBX만 기준으로 사용 (GPU 효율적 인스턴싱)
			const fbx = await loadFBX(process.env.PUBLIC_URL + '/static/data/model/' + files[0], scale);

			const meshes: THREE.Mesh[] = [];
			fbx.traverse((child) => {
				if (child.isMesh) {
					child.rotation.x = Math.PI / 2;
					meshes.push(child);
				}
			});

			const positions = [-100, 100];
			const group = new THREE.Group();

			meshes.forEach((mesh) => {
				const inst = new THREE.InstancedMesh(mesh.geometry, mesh.material, positions.length);
				const dummy = new THREE.Object3D();
				for (let i = 0; i < positions.length; i++) {
					dummy.position.set(positions[i], y, z);
					dummy.rotation.copy(mesh.rotation);
					dummy.scale.set(scale, scale, scale);
					dummy.updateMatrix();
					inst.setMatrixAt(i, dummy.matrix);
				}
				inst.instanceMatrix.needsUpdate = true;
				group.add(inst);
			});

			this.appCore.threeCore.scene.add(group);
		} catch (error) {
			console.error('fail to load :', error);
		}
	};
}
