import * as THREE from 'three';

import { CameraWrapper } from './Wrapper/CameraWrapper';
import { EventWrapper } from './Wrapper/EventWrapper';
import { LightWrapper } from './Wrapper/LightWrapper';
import { CLICK_TYPE } from '../Utils/const';

export class ThreeCore {
	public canvas: HTMLCanvasElement;
	public host: HTMLElement;
	public ctx: CanvasRenderingContext2D;
	public t: number = 0.0;

	public scene: THREE.Scene;
	public renderer: THREE.WebGLRenderer;
	public requestFrame: number;

	public loaded = false;
	public ready = false;

	public cameraWrapper: CameraWrapper;
	public lightWrapper: LightWrapper;
	public eventWrapper: EventWrapper;

	public animation: boolean = true;

	public groundReflector;

	constructor(id: string) {
		this.init(id);
	}
	async init(id) {
		this.initRenderer(id);
		this.lightWrapper = new LightWrapper(this);
		this.eventWrapper = new EventWrapper(this);
		this.cameraWrapper = new CameraWrapper(this);

		this.eventBind();
		this.loop();
	}

	public initRenderer(id: string) {
		THREE.Object3D.DEFAULT_UP.set(0, 0, 1);

		this.host = document.getElementById(id);

		this.scene = new THREE.Scene();
		this.scene.background = new THREE.Color(0, 0, 0);
		this.scene.castShadow = true;

		this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
		this.renderer.setPixelRatio(this.host.clientWidth / this.host.clientHeight);
		this.renderer.domElement.id = 'Three';

		this.renderer.shadowMap.enabled = true;
		this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
		this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
		this.renderer.toneMappingExposure = 1.2;
		this.renderer.outputColorSpace = THREE.SRGBColorSpace;
		this.renderer.localClippingEnabled = true;

		this.renderer.setSize(this.host.clientWidth, this.host.clientHeight);
		this.host.appendChild(this.renderer.domElement);

		this.scene.background = new THREE.Color(0xffffff);
		// this.scene.background = new THREE.Color(0x000000);
	}
	public initHDRI(name: string) {
		this.lightWrapper.updateHDRI(name);
	}
	public updateSolarVec(x: number, y: number, z: number) {
		this.lightWrapper.updateDirectionalLightVec(x, y, z);
	}
	private eventBind() {
		this.eventWrapper.InitNativeMouseEvent(this.renderer.domElement);
		window.addEventListener('resize', () => this.onWindowResize());
	}
	private onWindowResize() {
		this.cameraWrapper.onWindowResize();

		this.renderer.setSize(this.host.clientWidth, this.host.clientHeight);
	}
	public loop = () => {
		this.requestFrame = requestAnimationFrame(this.loop);

		if (this.loaded && this.ready) {
			// console.log('rendering...');
			this.cameraWrapper.update();
			this.update();

			if (this.lightWrapper.needPostProcessing) {
				// this.groundReflector.visible = false; // 자기 자신 반사 제외
				this.renderer.setRenderTarget(this.lightWrapper.reflectorRT);
				this.renderer.render(this.scene, this.cameraWrapper.camera);
				this.groundReflector.visible = true;

				this.lightWrapper.blurComposer.render();

				this.groundReflector.material.uniforms.tDiffuse.value = this.lightWrapper.blurredReflectionRT.texture;
				console.log(this.groundReflector.material.uniforms.tDiffuse.value);

				this.lightWrapper.composer.render();
			} else {
				this.renderer.render(this.scene, this.cameraWrapper.camera);
			}

			// console.log('working');

			this.t += 0.01;
		}
	};
	public togglePostProcessing() {
		this.lightWrapper.togglePostProcessing();
	}
	public destroy() {
		window.removeEventListener('resize', () => this.onWindowResize());
		cancelAnimationFrame(this.requestFrame);
		this.requestFrame = undefined;
		while (this.host.lastChild) {
			this.host.removeChild(this.host.lastChild);
		}
	}
	public onMouseEventListener = (e: MouseEvent, type: CLICK_TYPE) => {};
	public update() {}
}
